Az alábbi kód egy Flask alapú Python backendből hívja az Amazon Bedrockon futó Claude Opus 4.5 modellt a Bedrock Runtime SDK-val, és egy egyszerű, iOS‑szerű chat UI-t szolgál ki böngészőben, Replitre optimalizálva. A backend a `global.anthropic.claude-opus-4-5-20251101-v1:0` inference profile ID-t használja, amelyet az AWS Claude Opus 4.5 dokumentáció is bemutat, míg a frontenden klasszikus iOS chat‑szerű buborékos elrendezés készül. A kód AWS hitelesítést az AWS szabványos környezeti változóin keresztül vár (pl. `AWS_ACCESS_KEY_ID`, `AWS_SECRET_ACCESS_KEY`) és a Bedrock Runtime `invoke_model` metódusával küldi a messages‑formátumú kéréseket.[1][2][3][4][5][6][7]

## Backend main.py

```python
import os
import json
from flask import Flask, request, jsonify, send_from_directory
import boto3
from botocore.exceptions import BotoCoreError, ClientError

app = Flask(__name__, static_folder=".", static_url_path="")

aws_region = os.environ.get("AWS_REGION", "us-east-1")
bedrock_model_id = os.environ.get("BEDROCK_MODEL_ID", "global.anthropic.claude-opus-4-5-20251101-v1:0")

bedrock_client = boto3.client(
    service_name="bedrock-runtime",
    region_name=aws_region
)


def call_bedrock_claude(messages):
    request_body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": 1024,
        "temperature": 0.7,
        "messages": messages
    }
    response = bedrock_client.invoke_model(
        modelId=bedrock_model_id,
        body=json.dumps(request_body)
    )
    raw_body = response.get("body")
    if hasattr(raw_body, "read"):
        body_bytes = raw_body.read()
    else:
        body_bytes = raw_body
    decoded = body_bytes.decode("utf-8") if isinstance(body_bytes, (bytes, bytearray)) else str(body_bytes)
    data = json.loads(decoded)
    content_blocks = data.get("content", [])
    text_parts = []
    for block in content_blocks:
        if isinstance(block, dict) and block.get("type") == "text":
            text_value = block.get("text")
            if isinstance(text_value, str):
                text_parts.append(text_value)
    return "".join(text_parts)


@app.route("/", methods=["GET"])
def index():
    return send_from_directory(".", "index.html")


@app.route("/api/chat", methods=["POST"])
def chat():
    if not request.is_json:
        return jsonify({"error": "Invalid content type, expected application/json"}), 400
    payload = request.get_json(silent=True)
    if payload is None:
        return jsonify({"error": "Invalid JSON payload"}), 400
    messages = payload.get("messages")
    if not isinstance(messages, list) or len(messages) == 0:
        return jsonify({"error": "Field 'messages' must be a non-empty list"}), 400
    normalized_messages = []
    for item in messages:
        if not isinstance(item, dict):
            return jsonify({"error": "Each message must be an object"}), 400
        role = item.get("role")
        content = item.get("content")
        if role not in ["user", "assistant"]:
            return jsonify({"error": "Message role must be 'user' or 'assistant'"}), 400
        if not isinstance(content, str) or content.strip() == "":
            return jsonify({"error": "Message content must be a non-empty string"}), 400
        normalized_messages.append({"role": role, "content": content})
    try:
        assistant_reply = call_bedrock_claude(normalized_messages)
    except (BotoCoreError, ClientError) as e:
        return jsonify({"error": "Bedrock invocation failed", "details": str(e)}), 502
    except Exception as e:
        return jsonify({"error": "Unexpected server error", "details": str(e)}), 500
    return jsonify({"message": assistant_reply})


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    app.run(host="0.0.0.0", port=port)
```

