    const messagesState = [];
    const messagesInner = document.getElementById("messages-inner");
    const messagesScroll = document.getElementById("messages-scroll");
    const inputText = document.getElementById("input-text");
    const sendButton = document.getElementById("send-button");
    const errorBanner = document.getElementById("error-banner");
    let typingElement = null;
    function appendMessage(role, text) {
        const row = document.createElement("div");
        row.className = "message-row " + role;
        const bubble = document.createElement("div");
        bubble.className = "bubble " + role;
        bubble.textContent = text;
        row.appendChild(bubble);
        messagesInner.appendChild(row);
        scrollToBottom();
    }
    function showTypingIndicator() {
        if (typingElement !== null) {
            return;
        }
        const row = document.createElement("div");
        row.className = "message-row assistant";
        const typing = document.createElement("div");
        typing.className = "typing-indicator";
        for (let i = 0; i < 3; i++) {
            const dot = document.createElement("div");
            dot.className = "typing-dot";
            typing.appendChild(dot);
        }
        row.appendChild(typing);
        messagesInner.appendChild(row);
        typingElement = row;
        scrollToBottom();
    }
    function hideTypingIndicator() {
        if (typingElement !== null && typingElement.parentNode) {
            typingElement.parentNode.removeChild(typingElement);
        }
        typingElement = null;
    }
    function scrollToBottom() {
        requestAnimationFrame(function () {
            messagesScroll.scrollTop = messagesScroll.scrollHeight;
        });
    }
    function setError(message) {
        if (!message) {
            errorBanner.style.display = "none";
            errorBanner.textContent = "";
            return;
        }
        errorBanner.textContent = message;
        errorBanner.style.display = "block";
    }
    function setSendingState(isSending) {
        sendButton.disabled = isSending || !inputText.value.trim();
        inputText.disabled = isSending;
    }
    function resizeInput() {
        inputText.style.height = "24px";
        const newHeight = Math.min(inputText.scrollHeight, 96);
        inputText.style.height = newHeight + "px";
    }
    async function sendMessage() {
        const text = inputText.value.trim();
        if (!text) {
            return;
        }
        setError("");
        appendMessage("user", text);
        messagesState.push({ role: "user", content: text });
        inputText.value = "";
        resizeInput();
        setSendingState(true);
        showTypingIndicator();
        try {
            const response = await fetch("/api/chat", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({ messages: messagesState })
            });
            const data = await response.json();
            hideTypingIndicator();
            if (!response.ok) {
                const msg = data && data.error ? data.error : "Ismeretlen hiba történt a kiszolgálón.";
                setError(msg);
                setSendingState(false);
                return;
            }
            const assistantText = typeof data.message === "string" ? data.message : "";
            if (assistantText) {
                appendMessage("assistant", assistantText);
                messagesState.push({ role: "assistant", content: assistantText });
            } else {
                setError("A modell válasza üres volt.");
            }
        } catch (e) {
            hideTypingIndicator();
            setError("Nem sikerült csatlakozni a szerverhez.");
        } finally {
            setSendingState(false);
        }
    }
    sendButton.addEventListener("click", function () {
        sendMessage();
    });
    inputText.addEventListener("input", function () {
        resizeInput();
        if (!inputText.disabled) {
            sendButton.disabled = !inputText.value.trim();
        }
    });
    inputText.addEventListener("keydown", function (event) {
        if (event.key === "Enter" && !event.shiftKey) {
            event.preventDefault();
            if (!sendButton.disabled) {
                sendMessage();
            }
        }
    });
    window.addEventListener("load", function () {
        resizeInput();
        sendButton.disabled = true;
    });
</script>
