import os
import requests
from flask import Flask, request, jsonify, send_from_directory

app = Flask(__name__)

AI_GATEWAY_BASE_URL = ""
MODEL_ID = "openai/gpt-5-pro"


def get_api_key():
    api_key = os.getenv("AI_GATEWAY_API_KEY") or os.getenv("VERCEL_OIDC_TOKEN") or os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("Missing AI Gateway API key. Set AI_GATEWAY_API_KEY or VERCEL_OIDC_TOKEN environment variable")
    return api_key


@app.route("/", methods=["GET"])
def index():
    return send_from_directory(".", "index.html")


@app.route("/api/chat", methods=["POST"])
def chat():
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Invalid JSON payload"}), 400

    messages = data.get("messages")
    if not isinstance(messages, list) or not messages:
        return jsonify({"error": "messages must be a non-empty list"}), 400

    api_messages = []

    for message in messages:
        if not isinstance(message, dict):
            return jsonify({"error": "Each message must be an object"}), 400
        role = message.get("role")
        content = message.get("content")
        if role not in ("user", "assistant", "system"):
            return jsonify({"error": "Invalid message role"}), 400
        if not isinstance(content, str) or not content.strip():
            return jsonify({"error": "Message content must be a non-empty string"}), 400
        api_messages.append({"role": role, "content": content})

    payload = {
        "model": MODEL_ID,
        "messages": api_messages,
        "temperature": 0.7,
        "max_tokens": 2048,
        "stream": False
    }

    try:
        api_key = get_api_key()
    except RuntimeError as e:
        return jsonify({"error": str(e)}), 500

    try:
        response = requests.post(
            f"{AI_GATEWAY_BASE_URL}/chat/completions",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json"
            },
            json=payload,
            timeout=60
        )
    except requests.Timeout:
        return jsonify({"error": "Request timeout. The AI Gateway took too long to respond."}), 504
    except requests.ConnectionError:
        return jsonify({"error": "Connection error. Cannot reach AI Gateway at " + AI_GATEWAY_BASE_URL}), 502
    except requests.RequestException as e:
        return jsonify({"error": "Request failed: " + str(e)}), 502

    if response.status_code != 200:
        error_detail = response.text
        try:
            error_json = response.json()
            if "error" in error_json:
                error_detail = error_json.get("error", {}).get("message", error_detail)
        except Exception:
            pass

        return jsonify(
            {
                "error": f"AI Gateway error (HTTP {response.status_code})",
                "details": error_detail
            }
        ), response.status_code

    try:
        completion = response.json()
        choices = completion.get("choices")
        if not choices or len(choices) == 0:
            return jsonify({"error": "No response from AI model"}), 500
        message_content = choices[0].get("message", {}).get("content", "")
        if not message_content:
            return jsonify({"error": "Empty response from AI model"}), 500
    except Exception as e:
        return jsonify({"error": "Invalid response from AI Gateway: " + str(e)}), 502

    return jsonify({"reply": message_content})


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    print(f"Starting Flask server on port {port}")
    print(f"AI Gateway URL: {AI_GATEWAY_BASE_URL}")
    print(f"Model: {MODEL_ID}")
    try:
        get_api_key()
        print("API key found")
    except RuntimeError as e:
        print(f"WARNING: {e}")
    app.run(host="0.0.0.0", port=port, debug=False)
