    }
];

var chatContainer = document.getElementById("chat-container");
var typingRow = document.getElementById("typing-row");
var messageInput = document.getElementById("message-input");
var sendButton = document.getElementById("send-button");
var chatForm = document.getElementById("chat-form");
var dateLabel = document.getElementById("date-label");

function formatDateLabel(date) {
    var months = [
        "január",
        "február",
        "március",
        "április",
        "május",
        "június",
        "július",
        "augusztus",
        "szeptember",
        "október",
        "november",
        "december"
    ];
    var day = date.getDate();
    var month = months[date.getMonth()];
    var year = date.getFullYear();
    return day + ". " + month + " " + year + ".";
}

function formatTime(date) {
    var h = date.getHours();
    var m = date.getMinutes();
    if (m < 10) {
        m = "0" + m;
    }
    return h + ":" + m;
}

function setDateLabel() {
    var now = new Date();
    dateLabel.textContent = formatDateLabel(now);
}

function clearChatMessages() {
    var children = Array.prototype.slice.call(chatContainer.children);
    for (var i = 0; i < children.length; i++) {
        var node = children[i];
        if (node === dateLabel || node === typingRow) {
            continue;
        }
        chatContainer.removeChild(node);
    }
}

function renderMessages() {
    clearChatMessages();
    for (var i = 0; i < messages.length; i++) {
        var message = messages[i];
        var messageRow = document.createElement("div");
        var roleClass = message.role === "user" ? "user" : "assistant";
        messageRow.className = "message-row " + roleClass;

        var bubbleContainer = document.createElement("div");
        var bubble = document.createElement("div");
        bubble.className = "message-bubble " + roleClass;
        bubble.textContent = message.content;

        var meta = document.createElement("div");
        meta.className = "message-meta " + roleClass;
        if (message.timestamp) {
            meta.textContent = message.timestamp;
        } else {
            meta.textContent = message.role === "user" ? "Te" : "Asszisztens";
        }

        bubbleContainer.appendChild(bubble);
        bubbleContainer.appendChild(meta);
        messageRow.appendChild(bubbleContainer);

        chatContainer.insertBefore(messageRow, typingRow);
    }
    scrollToBottom();
}

function scrollToBottom() {
    chatContainer.scrollTop = chatContainer.scrollHeight;
}

function setSendingState(isSending) {
    if (isSending) {
        sendButton.classList.add("disabled");
        sendButton.disabled = true;
        typingRow.classList.add("visible");
    } else {
        sendButton.classList.remove("disabled");
        sendButton.disabled = false;
        typingRow.classList.remove("visible");
    }
}

function addUserMessage(text) {
    var now = new Date();
    messages.push({
        role: "user",
        content: text,
        timestamp: formatTime(now)
    });
    renderMessages();
}

function addAssistantMessage(text) {
    var now = new Date();
    messages.push({
        role: "assistant",
        content: text,
        timestamp: formatTime(now)
    });
    renderMessages();
}

function addErrorMessage(text) {
    var now = new Date();
    var messageRow = document.createElement("div");
    messageRow.className = "message-row assistant";

    var bubbleContainer = document.createElement("div");
    var bubble = document.createElement("div");
    bubble.className = "message-bubble assistant error-bubble";
    bubble.textContent = text;

    var meta = document.createElement("div");
    meta.className = "message-meta assistant";
    meta.textContent = formatTime(now);

    bubbleContainer.appendChild(bubble);
    bubbleContainer.appendChild(meta);
    messageRow.appendChild(bubbleContainer);

    chatContainer.insertBefore(messageRow, typingRow);
    scrollToBottom();
}

async function sendMessageToBackend() {
    var payload = {
        messages: messages.map(function(message) {
            return {
                role: message.role,
                content: message.content
            };
        })
    };

    try {
        var response = await fetch("/api/chat", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(payload)
        });

        var data = await response.json();

        if (!response.ok) {
            var errorText = "Hiba: ";
            if (data && data.error) {
                errorText += data.error;
                if (data.details) {
                    errorText += " - " + data.details;
                }
            } else {
                errorText += "HTTP " + response.status;
            }
            addErrorMessage(errorText);
            return;
        }

        if (data && typeof data.reply === "string") {
            addAssistantMessage(data.reply);
        } else {
            addErrorMessage("Érvénytelen válasz a szervertől.");
        }
    } catch (e) {
        addErrorMessage("Nem sikerült csatlakozni a szerverhez. Ellenőrizd a hálózati kapcsolatot.");
    }
}

chatForm.addEventListener("submit", function (event) {
    event.preventDefault();
    var value = messageInput.value.trim();
    if (!value || sendButton.disabled) {
        return;
    }
    addUserMessage(value);
    messageInput.value = "";
    autoResizeTextarea();
    setSendingState(true);
    sendMessageToBackend().finally(function () {
        setSendingState(false);
    });
});

messageInput.addEventListener("input", function () {
    autoResizeTextarea();
});

function autoResizeTextarea() {
    messageInput.style.height = "auto";
    var newHeight = messageInput.scrollHeight;
    if (newHeight > 88) {
        newHeight = 88;
    }
    messageInput.style.height = newHeight + "px";
}

messageInput.addEventListener("keydown", function (event) {
    if (event.key === "Enter" && !event.shiftKey) {
        event.preventDefault();
        chatForm.dispatchEvent(new Event("submit"));
    }
});

setDateLabel();
renderMessages();
scrollToBottom();
autoResizeTextarea();
</script>
</body>
</html>
